<script setup lang="ts">
import {ref,onMounted} from 'vue'
import AssuranceFollowUpPolicy from './AssuranceFollowUpPolicy.vue'
import AssuranceTaskAssignment from './AssuranceTaskAssignment.vue'
const props=defineProps<{role:string;portal:(path:string,body?:any)=>Promise<any>;request:(path:string,body?:any,method?:string)=>Promise<any>}>()
const emit=defineEmits<{changed:[]}>()
const rows=ref<any[]>([]),count=ref(0),page=ref(1),state=ref('open'),error=ref(''),busy=ref(false),resolution=ref(''),selected=ref<any>(null)
const reassignment=ref<any>(null)
const reopening=ref(false)
const planning=ref<any>(null),priority=ref('normal'),due=ref(''),reason=ref(''),history=ref<any[]>([]),historyPage=ref(1),historyCount=ref(0),historyRow=ref<any>(null)
async function plan(){busy.value=true;error.value='';try{await props.request(`follow-ups/${planning.value.id}/${reopening.value?'reopen':'plan'}/?state=all`,{revision:planning.value.revision,priority:priority.value,due_at:due.value,reason:reason.value});planning.value=null;emit('changed');await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function loadHistory(){busy.value=true;error.value='';try{const data=await props.request(`follow-ups/${historyRow.value.id}/history/?state=all&page=${historyPage.value}`);history.value=data.results;historyCount.value=data.count}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function load(){busy.value=true;error.value='';try{const data=await props.request(`follow-ups/?state=${state.value}&page=${page.value}`);rows.value=data.results;count.value=data.count}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function close(){busy.value=true;error.value='';try{await props.request(`follow-ups/${selected.value.id}/close/`,{resolution:resolution.value,revision:selected.value.revision});selected.value=null;resolution.value='';emit('changed');await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
onMounted(load)
</script>
<template><section><AssuranceFollowUpPolicy v-if="role==='administrator'" :request="request"/><h3>Tâches de suivi</h3><p>Les tâches ouvertes restent signalées jusqu’à une clôture justifiée. Les nouvelles tâches suivent les règles définies par l’administration.</p><p v-if="error" role="alert">{{error}}</p><label>Afficher<select v-model="state" @change="page=1;load()"><option value="open">Ouvertes</option><option value="closed">Clôturées</option><option value="all">Toutes</option></select></label><button class="secondary" :disabled="busy" @click="load">Actualiser</button><article v-for="row in rows" :key="row.id"><h4>Tâche {{row.id}} · {{row.contact_name||'Prospect'}} · {{row.appointment_id?'RDV '+row.appointment_id:'Rappel contact'}}</h4><p>{{row.reason}}</p><p v-if="role==='administrator'">Responsable du suivi : {{row.assigned_setter_id}} · Setter d’origine du RDV : {{row.original_setter_id??'Sans RDV'}}</p><button v-if="role==='administrator'&&!row.closed_at" class="secondary" :disabled="busy" @click="reassignment=row">Réattribuer</button><p v-if="row.latest_incident">Dernier signalement : {{row.latest_incident.note}} · {{new Date(row.latest_incident.created_at).toLocaleString('fr-FR')}}</p><p>Priorité : {{row.priority}} · Échéance : {{new Date(row.due_at).toLocaleString('fr-FR')}}</p><p v-if="row.overdue">Échéance dépassée</p><button v-if="role==='administrator'&&!row.closed_at" class="secondary" @click="reopening=false;planning=row;priority=row.priority;due=row.due_at;reason=''">Priorité et échéance</button><button v-if="role==='administrator'" class="secondary" @click="historyRow=row;historyPage=1;loadHistory()">Historique</button><button v-if="role==='administrator'&&row.closed_at" class="secondary" :disabled="busy" @click="reopening=true;planning=row;priority=row.priority;due=new Date(Date.now()+24*3600000).toISOString();reason=''">Rouvrir avec justification</button><p v-if="row.closed_at">Clôturée : {{row.resolution}}</p><button v-else class="secondary" :disabled="busy" @click="selected=row;resolution=''">Clôturer avec justification</button></article><p v-if="!rows.length">Aucune tâche.</p><p>{{count}} tâche(s) · page {{page}}</p><button class="secondary" :disabled="busy||page===1" @click="page--;load()">Précédent</button><button class="secondary" :disabled="busy||page*25>=count" @click="page++;load()">Suivant</button><AssuranceTaskAssignment v-if="role==='administrator'&&reassignment" :key="reassignment.id" :task="reassignment" :portal="portal" :request="request" @cancel="reassignment=null" @saved="reassignment=null;emit('changed');load()"/><form v-if="selected" @submit.prevent="close"><label>Justification de clôture<textarea v-model="resolution" required maxlength="3000"></textarea></label><button class="primary" :disabled="busy">Confirmer la clôture</button><button type="button" class="secondary" @click="selected=null">Annuler</button></form><form v-if="planning" @submit.prevent="plan"><h4>{{reopening?'Rouvrir la tâche clôturée':'Planifier la tâche ouverte'}}</h4><p v-if="reopening">La clôture précédente restera dans l’historique. La tâche sera rendue au même setter avec la nouvelle échéance.</p><label>Priorité<select v-model="priority"><option value="low">Basse</option><option value="normal">Normale</option><option value="high">Haute</option><option value="urgent">Urgente</option></select></label><label>Échéance ISO 8601 avec décalage<input v-model="due" required></label><label>Motif de modification<textarea v-model="reason" required maxlength="1000"></textarea></label><button class="primary" :disabled="busy">{{reopening?'Confirmer la réouverture':'Enregistrer la planification'}}</button><button type="button" class="secondary" @click="planning=null">Annuler</button></form><section v-if="historyRow"><h4>Historique de la tâche {{historyRow.id}}</h4><article v-for="entry in history" :key="entry.id"><p>{{entry.action}} · {{new Date(entry.created_at).toLocaleString('fr-FR')}} · utilisateur {{entry.actor_id}}</p><pre>{{JSON.stringify(entry.metadata,null,2)}}</pre></article><button class="secondary" :disabled="busy||historyPage===1" @click="historyPage--;loadHistory()">Précédent</button><button class="secondary" :disabled="busy||historyPage*25>=historyCount" @click="historyPage++;loadHistory()">Suivant</button><button class="secondary" @click="historyRow=null">Fermer l’historique</button></section></section></template>
